function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 150) return 'mat needs 1 to 150 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 150) return 'Each row needs 1 to 150 cells.';
  for (const row of mat) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell must be 0 or 1.';
  }
  return null;
}

