function numSubmat(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const heights = new Array(cols).fill(0);
  let total = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      heights[c] = mat[r][c] === 1 ? heights[c] + 1 : 0;
    }
    const stack = [];
    const ending = new Array(cols).fill(0);
    for (let c = 0; c < cols; c++) {
      while (stack.length > 0 && heights[stack[stack.length - 1]] >= heights[c]) {
        stack.pop();
      }
      if (stack.length > 0) {
        const prev = stack[stack.length - 1];
        ending[c] = ending[prev] + heights[c] * (c - prev);
      } else {
        ending[c] = heights[c] * (c + 1);
      }
      stack.push(c);
      total += ending[c];
    }
  }
  return total;
}

