function numSubmat(mat) {
  const m = mat.length, n = mat[0].length;
  // prefix[i][j] = number of ones in the block of rows < i and columns < j.
  const prefix = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      prefix[i + 1][j + 1] = mat[i][j] + prefix[i][j + 1] + prefix[i + 1][j] - prefix[i][j];
  let count = 0;
  for (let top = 0; top < m; top++)
    for (let bottom = top; bottom < m; bottom++)
      for (let left = 0; left < n; left++)
        for (let right = left; right < n; right++) {
          const ones = prefix[bottom + 1][right + 1] - prefix[top][right + 1] - prefix[bottom + 1][left] + prefix[top][left];
          if (ones === (bottom - top + 1) * (right - left + 1)) count++;
        }
  return count;
}

