function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const m = large ? int(80, 100) : int(1, 6);
  const n = large ? int(80, 100) : int(1, 6);
  const style = int(0, 3);
  const density = style === 0 ? 1 : style === 1 ? 0.95 : style === 2 ? 0.7 : 0.4;
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [mat];
}
